  1	# M1 — 과거 경로와 현재 데이터의 호환 범위
  2	
  3	작성: 2026-09-23. 과거 `038b253e`, 현재 `061cc138722714ecaf76ca2d3fb4467481701545`.
  4	원본 6개는 `source/legacy_origin/`에 경로 구조대로 추출했다. 출처·SHA-256은 `summary/origin_manifest.json`.
  5	정적 대조 완료이며 실제 표시·입력 충실도는 M3 검증 전이다. 수치는 아직 없다.
  6	
  7	| 호출 | 과거 | 현재 | 결정 및 비용 포함 | 오차 방향 |
  8	|---|---|---|---|---|
  9	| GetHoveredCell | 평면 역변환과 y 오프셋 | 단차 인지 PickCellAtWorldPoint | 양쪽 현재 입력 함수를 공유. 호버 전체 시간에 포함. 동일 셀 입력을 위한 호환 변경 | 모름 |
 10	| GetChunkAt | 9×9 좌표 산술 + 청크 사전 | 셀→청크 사전 + 청크 사전 | 현재 API 사용, 호버 시간에 포함 | 모름 |
 11	| Chunk.Cells | IReadOnlyList<GridCell> | 동일 노출 타입, 가변 청크 | 현재 실제 셀 목록. 읽기·순회 비용 포함 | 원본 맵과 규모가 다름 |
 12	| GetChunkCellCoords | Count 용량의 새 List, 셀 Coord 복사 | 해당 경로 없음 | S0 원문 이식, 매 프레임 할당·복사 포함 | 로직 보존 |
 13	| CanSendExpedition | Visible, 상하좌우 점령 이웃, 중복 원정 검사 | Visible, 실제 경계 이웃, 중복 원정 검사 | 현재 API 공유, S0 호버 시간에 포함. 이웃 정의는 현재 지형에 맞춤 | 모름 |
 14	| HighlightCells | Get→좌표 변환+yOffset→위치/색→DeactivateFrom | 초기화 확인·맥동 정리·sprite 복원·표면 좌표 사용 | S0 과거 루프 이식. 현재 HighlightCells 호출 금지. 루프 전부 포함 | 좌표 어댑터 차이는 아래 참고 |
 15	| ConvertGridToWorld | Tilemap.GetCellCenterWorld | 위 호출 + GetHeightOffset | 현재 함수를 사용해 단차에 대응. 과거 루프의 yOffset 덧셈 유지. 오프셋은 명시적 설정·기록, 표시 검증 필요 | 추가 조회가 있으나 전체 방향 모름 |
 16	| ComponentPool | 인덱스 풀, seed 0번, Get의 SetActive | 실행 코드 동일, 주석 1줄 변경 | 현재 클래스 공유. Get/Deactivate 포함, 생성은 초기화 별도 | 실행 로직 동일 |
 17	| ClearHighlights | 자기 풀 DeactivateAll | 선택 풀·맥동 정리 | S0 자기 풀만 비활성화. 빈 영역 처리 비용 포함 | 로직 보존 |
 18	
 19	## 판정 규칙 대조
 20	
 21	CanSendExpedition의 상위 검사 순서는 같지만 HasConqueredOrthogonalNeighbor의 이웃 조회가
 22	GetOrthogonalAdjacentChunks에서 GetBorderingChunks로 바뀌었다. 비용·의미 모두 완전히 동일하다고 할 수 없다.
 23	현재 가변 청크 맵에서 과거 9×9 산술을 재사용하지 않는다. 이 비교는 현재 데이터 어댑터 위의
 24	과거 표시 처리 경로와 현재 실제 구현 비교이며, 과거 게임 전체 실행의 완전 재현이 아니다.
 25	
 26	## 풀 초기화 결정
 27	
 28	초기화 때 한 번 현재 `_selectionHighlightRenderer`를 리플렉션으로 읽는다. 과거 이름은 `_spriteRenderer`다.
 29	현재 선택 풀을 공유하지 않고 벤치 루트에 독립 SpriteRenderer를 준비한다. sprite/material/정렬/스케일을
 30	기록·검증하고 템플릿과 seedInstance에 같은 렌더러를 전달해 0번 재사용을 유지한다.
 31	컨트롤러 GameObject 전체는 복제하지 않는다. 원본 부모 대신 벤치 루트를 쓰는 차이는 격리 목적이다.
 32	생성·참조 획득은 초기화 구간으로 분리한다. 현재 에셋을 사용하므로 과거 렌더링 에셋 재현이라고 부르지 않는다.
 33	
 34	## 다음 단계와 제약
 35	
 36	M2는 구현 전 Coplay 연결 확인이 필요하다. 이 세션의 전체 도구 목록에서 Coplay 도구를 찾지 못했다.
 37	Unity 컴파일·씬·스냅샷·플레이 확인을 다른 도구로 우회하지 않는다. M1은 정적 대조 완료,
 38	M2~M3의 실제 경로·표시·입력 검증은 미수행이다.
  1	// 점령 하이라이트 실측 하네스 - 측정 전용. 커밋 대상이 아니며 M8에서 삭제한다.
  2	
  3	using System.Collections.Generic;
  4	using System.Reflection;
  5	using Unity.Profiling;
  6	using UnityEngine;
  7	
  8	/// <summary>
  9	/// 038b253e의 점령 하이라이트 처리 경로(S0)를 현재 데이터 위에 이식한 드라이버.
 10	///
 11	/// 이식 방침은 bench/2026-09-23_playmode/호환범위.md(M1 대조표)가 기준이다. 요지:
 12	/// <list type="bullet">
 13	/// <item>입력(<c>GetHoveredCell</c>)·청크 조회(<c>GetChunkAt</c>)·판정(<c>CanSendExpedition</c>)은
 14	/// <b>현재 API를 공유</b>한다. 두 변형이 같은 프레임에 같은 셀을 봐야 입력 충실도 관문(§2-2-1)이 성립한다.</item>
 15	/// <item>표시 루프는 <b>과거 원문 그대로</b>다. 매 프레임 <c>new List&lt;Vector3Int&gt;</c>를 만들고
 16	/// 변경 가드 없이 다시 칠한다 - 그 할당이 곧 측정 대상이므로 줄이지 않는다.</item>
 17	/// <item>현재 <c>MouseSelectController.HighlightCells</c>는 부르지 않는다(초기화 확인·맥동 정리·
 18	/// 스프라이트 복원·표면 좌표가 얹혀 있어 과거 루프가 아니다). 자기 풀을 따로 갖는다.</item>
 19	/// <item>좌표는 현재 <c>ConvertGridToWorld</c>(단차 반영)를 쓰고 과거 루프의 yOffset 덧셈을 유지한다.</item>
 20	/// </list>
 21	///
 22	/// Update 실행 순서는 기본값으로 둔다 - T1의 ConquestModeController.Update와 같은 자리에서 돌아야
 23	/// 같은 조건의 비교가 된다. 하네스만 -1000으로 앞세운다.
 24	/// </summary>
 25	public sealed class LegacyConquestHighlightDriver : MonoBehaviour
 26	{
 27	    private static readonly ProfilerMarker HOVER_MARKER = new(BenchMarkerNames.S0_HOVER);
 28	    private static readonly ProfilerMarker REBUILD_MARKER = new(BenchMarkerNames.S0_REBUILD);
 29	
 30	    // 과거 인스펙터 기본값을 그대로 옮긴다(038b253e ConquestModeController).
 31	    private static readonly Color CONQUERABLE_HIGHLIGHT_COLOR = Color.green;
 32	    private static readonly Color BLOCKED_HIGHLIGHT_COLOR = Color.red;
 33	
 34	    private const string LEGACY_SEED_OBJECT_NAME = "[BENCH] S0 Highlight Seed";
 35	    private const string CURRENT_SELECTION_RENDERER_FIELD = "_selectionHighlightRenderer";
 36	
 37	    private GridMap _gridMap;
 38	    private MouseSelectController _mouseSelectController;
 39	    private ConquestManager _conquestManager;
 40	
 41	    private ComponentPool<SpriteRenderer> _highlightPool;
 42	    private SpriteRenderer _seedRenderer;
 43	    private float _yOffset;
 44	
 45	    /// <summary>드라이버가 이번 프레임에 실제로 셀을 다시 칠했는가 - 하네스가 프레임별로 읽어 간다.</summary>
 46	    public bool DidRebuildThisFrame { get; private set; }
 47	
 48	    /// <summary>이번 프레임에 다시 칠한 셀 수. 0이면 빈 영역이라 풀만 껐다는 뜻이다.</summary>
 49	    public int LastRebuiltCellCount { get; private set; }
 50	
 51	    /// <summary>세션 누적 재구성 호출 수 - CSV의 "실제 재구성 횟수"에 들어간다.</summary>
 52	    public int RebuildCallCount { get; private set; }
 53	
 54	    /// <summary>초기화에서 잡은 seed 렌더러 - 파일럿(M3)이 스프라이트·정렬·스케일을 원본과 대조한다.</summary>
 55	    public SpriteRenderer SeedRenderer => _seedRenderer;
 56	
 57	    public bool IsReady { get; private set; }
 58	
 59	    /// <summary>
 60	    /// 풀 생성과 참조 획득은 <b>초기화 구간</b>이다 - 측정 프레임 밖에서 한 번만 부른다.
 61	    /// 실패하면 false를 돌려주고 드라이버는 돌지 않는다(빈 하이라이트로 조용히 측정되지 않게 한다).
 62	    /// </summary>
 63	    public bool Initialize(
 64	        GridMap gridMap,
 65	        MouseSelectController mouseSelectController,
 66	        ConquestManager conquestManager,
 67	        Transform benchRoot)
 68	    {
 69	        _gridMap = gridMap;
 70	        _mouseSelectController = mouseSelectController;
 71	        _conquestManager = conquestManager;
 72	
 73	        if (_gridMap == null || _mouseSelectController == null || _conquestManager == null || benchRoot == null)
 74	        {
 75	            Debug.LogError("[BENCH] S0 드라이버 초기화 실패 - 씬 참조가 비어 있다.");
 76	            return false;
 77	        }
 78	
 79	        _yOffset = _mouseSelectController.YOffset;
 80	
 81	        SpriteRenderer currentTemplate = ResolveCurrentSelectionRenderer(_mouseSelectController);
 82	        if (currentTemplate == null)
 83	        {
 84	            Debug.LogError($"[BENCH] S0 드라이버 초기화 실패 - MouseSelectController.{CURRENT_SELECTION_RENDERER_FIELD}를 찾지 못했다.");
 85	            return false;
 86	        }
 87	
 88	        // 현재 선택 풀을 공유하지 않는다 - T1이 같은 렌더러를 쓰면 두 구현의 표시가 섞인다(M3 격리 관문).
 89	        // 대신 같은 에셋을 쓰는 독립 복제본을 벤치 루트 아래에 만들고, 과거와 같이
 90	        // 그 복제본을 템플릿이자 seedInstance로 넘겨 0번 슬롯 재사용을 유지한다.
 91	        _seedRenderer = Instantiate(currentTemplate, benchRoot);
 92	        _seedRenderer.gameObject.name = LEGACY_SEED_OBJECT_NAME;
 93	        _seedRenderer.transform.localScale = currentTemplate.transform.lossyScale;
 94	        _seedRenderer.gameObject.SetActive(false);
 95	
 96	        _highlightPool = new ComponentPool<SpriteRenderer>(_seedRenderer, benchRoot, seedInstance: _seedRenderer);
 97	        _highlightPool.DeactivateAll();
 98	
 99	        IsReady = true;
100	        return true;
101	    }
102	
103	    /// <summary>현재 컨트롤러의 선택 하이라이트 템플릿을 리플렉션으로 한 번 읽는다(과거 이름은 _spriteRenderer).</summary>
104	    private static SpriteRenderer ResolveCurrentSelectionRenderer(MouseSelectController mouseSelectController)
105	    {
106	        FieldInfo field = typeof(MouseSelectController).GetField(
107	            CURRENT_SELECTION_RENDERER_FIELD,
108	            BindingFlags.Instance | BindingFlags.NonPublic);
109	
110	        return field?.GetValue(mouseSelectController) as SpriteRenderer;
111	    }
112	
113	    private void Update()
114	    {
115	        if (!IsReady)
116	            return;
117	
118	        DidRebuildThisFrame = false;
119	        LastRebuiltCellCount = 0;
120	
121	        using (HOVER_MARKER.Auto())
122	        {
123	            HighlightHoveredChunk();
124	        }
125	    }
126	
127	    // 038b253e ConquestModeController.HighlightHoveredChunk()의 원문 이식.
128	    // 변경 가드가 없다 - 같은 칸에 머무는 프레임에도 전부 다시 만든다.
129	    private void HighlightHoveredChunk()
130	    {
131	        Vector3Int hoveredCell = _mouseSelectController.GetHoveredCell();
132	        Chunk chunk = _gridMap.GetChunkAt(hoveredCell);
133	
134	        if (chunk == null)
135	        {
136	            ClearHighlights();
137	            return;
138	        }
139	
140	        Color color = _conquestManager.CanSendExpedition(chunk.ChunkCoord)
141	            ? CONQUERABLE_HIGHLIGHT_COLOR
142	            : BLOCKED_HIGHLIGHT_COLOR;
143	
144	        HighlightCells(GetChunkCellCoords(chunk), color);
145	    }
146	
147	    // 038b253e MouseSelectController.HighlightCells()의 원문 이식.
148	    // 좌표 변환만 현재 ConvertGridToWorld(단차 반영)를 쓰고, 과거의 yOffset 덧셈은 그대로 둔다.
149	    private void HighlightCells(List<Vector3Int> coords, Color color)
150	    {
151	        using (REBUILD_MARKER.Auto())
152	        {
153	            for (int i = 0; i < coords.Count; i++)
154	            {
155	                SpriteRenderer highlight = _highlightPool.Get(i);
156	                Vector3 cellPos = _gridMap.ConvertGridToWorld(coords[i]);
157	                cellPos.y += _yOffset;
158	                highlight.transform.position = cellPos;
159	                highlight.color = color;
160	            }
161	
162	            _highlightPool.DeactivateFrom(coords.Count);
163	        }
164	
165	        DidRebuildThisFrame = true;
166	        LastRebuiltCellCount = coords.Count;
167	        RebuildCallCount++;
168	    }
169	
170	    // 038b253e ConquestModeController.GetChunkCellCoords()의 원문 이식 -
171	    // 매 프레임 새 List를 만들고 셀 좌표를 복사한다. 이 할당을 없애지 않는다.
172	    private static List<Vector3Int> GetChunkCellCoords(Chunk chunk)
173	    {
174	        var coords = new List<Vector3Int>(chunk.Cells.Count);
175	        foreach (GridCell cell in chunk.Cells)
176	        {
177	            coords.Add(cell.Coord);
178	        }
179	
180	        return coords;
181	    }
182	
183	    // 038b253e MouseSelectController.ClearHighlights() - 자기 풀만 전부 비활성화한다.
184	    private void ClearHighlights()
185	    {
186	        using (REBUILD_MARKER.Auto())
187	        {
188	            _highlightPool.DeactivateAll();
189	        }
190	
191	        DidRebuildThisFrame = true;
192	        LastRebuiltCellCount = 0;
193	        RebuildCallCount++;
194	    }
195	
196	    /// <summary>측정 종료 후 표시를 거두고 벤치 오브젝트를 정리한다.</summary>
197	    public void Teardown()
198	    {
199	        IsReady = false;
200	
201	        _highlightPool?.DeactivateAll();
202	
203	        if (_seedRenderer != null)
204	            Destroy(_seedRenderer.gameObject);
205	    }
206	}
  1	# 보관 소스 변경 이력
  2	
  3	이 폴더는 측정을 다시 돌리거나 결과 표를 다시 만들 때 쓰는 소스의 보관본이다.
  4	`source.sha256`이 현재 목록이고, 옛 목록은 `history/`에 그대로 둔다.
  5	
  6	검증(이 폴더에서): `shasum -a 256 -c source.sha256`
  7	
  8	| 날짜 | 파일 | 바뀐 내용 | 이유 |
  9	|---|---|---|---|
 10	| 2026-09-26 | 전체 39파일 | M8에서 처음 보관(`bench_harness/`, `legacy_origin/`, `summarize.py`) | 측정 재현 자료 |
 11	| 2026-10-01 | `history/M8/summarize.py`, `history/M8/source.sha256` | M8 집계기와 M8 해시 목록을 **바이트 그대로** 복사해 보존. 복사본 해시 `d0e9cb0a…`가 옛 목록의 `./summarize.py` 항목과 같음을 확인 | 옛 출력 `summary/summarize_output.md`를 다시 만들 코드를 남기기 위해(N5) |
 12	| 2026-10-01 | `summarize.py` | `bench/summarize.py`의 N2·N3 개정판으로 교체(런 그룹 manifest, 측정 창 대응, 결함 수정, 구간 GC · 재구성 발생/미발생 · 프레임 대응 요약 · `floor(p·n)` 열) | 결과 문서 표를 그룹별 명령으로 재생성하기 위해. 개정 내용은 `../11_보완작업_마일스톤.md` N2·N3 |
 13	| 2026-10-01 | `test_summarize.py` | 새로 보관(회귀 테스트 38개) | 집계 정의를 테스트로 고정 |
 14	| 2026-10-01 | `source.sha256` | 새 목록. `history/`는 빼고, 이 폴더 밖의 재현 자료 `../runs_manifest.json`·`../raw_manifest.tsv`·`../raw_manifest.sha256`·`../summary/n3_checks/*.py`를 상대 경로로 포함 | 집계 입력 그룹과 대조 스크립트까지 함께 고정 |
 15	| 2026-10-01 | `history/2026-10-01_N5/source.sha256`, `source.sha256` | N5 목록(48항목)을 바이트 그대로 보존하고, 새 목록에 N6 산출물 `../summary/n6_capture/*.cs` 3개 · `../screenshots/profiler_*.png` 4개 · `../screenshots/profiler_captions.md`를 추가 | Codex 일괄 검토 R1-4(`../review/2026-10-01_N4-N6/`) — 화면을 다시 여는 스크립트가 목록에 없었다 |
 16	
 17	- `bench_harness/`·`legacy_origin/`는 바뀌지 않았다(새 목록의 해당 항목이 옛 목록과 같다).
 18	- 이 파일(`변경이력.md`)도 새 목록에 들어 있다. 이 파일을 고치면 목록을 다시 만들고 이전 목록을 `history/`에 남긴다.

