 13	public static class N6Show
 14	{
 15	    const string RAW_DIR = "bench/2026-09-23_playmode/raw";
 16	    const string FILTER = "TND.Bench";
 17	
 18	    public static string S0Still() => Show("S0_A_run4", 900);
 19	    public static string T1Still() => Show("T1_A_run4", 900);
 20	    public static string T1Rebuild() => Show("T1_D_run4", 896);
 21	    public static string ReentrySpike() => Show("T1_EReenter_run11", 30);
 22	
 23	    static string Show(string runId, int frame)
 24	    {
 25	        var sb = new StringBuilder();
 26	        string root = Directory.GetParent(Application.dataPath).FullName;
 27	        string path = Path.Combine(root, RAW_DIR, runId + ".raw");
 28	        if (!File.Exists(path)) return "raw 없음: " + path;
 29	
 30	        Type us = typeof(EditorWindow).Assembly.GetType("UnityEditor.Profiling.ProfilerUserSettings");
 31	        sb.AppendLine("frameCount 설정: " + us?.GetProperty("frameCount", BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic)?.GetValue(null));
 32	        if (!ProfilerDriver.LoadProfile(path, false)) return "raw 로드 실패: " + path;
 33	        sb.AppendLine($"로드 {runId}: 사용 가능 {ProfilerDriver.firstFrameIndex}~{ProfilerDriver.lastFrameIndex}");
 34	
 35	        ProfilerWindow w = EditorWindow.GetWindow<ProfilerWindow>();
 36	        w.Show();
 37	        if (w.maximized) w.maximized = false;
 38	        w.position = new Rect(80, 80, 1600, 1000);
 39	        SelectCpuModule(w, sb);
 40	        SetHierarchyView(w, sb);
 41	        w.selectedFrameIndex = frame;
 42	        var controller = w.GetFrameTimeViewSampleSelectionController(ProfilerWindow.cpuModuleIdentifier);
 43	        controller.sampleNameSearchFilter = FILTER;
 44	        w.Focus();
 45	        w.Repaint();
 46	        sb.AppendLine($"선택 프레임 {w.selectedFrameIndex}, 모듈 {w.selectedModuleIdentifier}, 검색 '{controller.sampleNameSearchFilter}', 최대화 {w.maximized}, 창 {w.position}");
 47	
 48	        using (var view = ProfilerDriver.GetHierarchyFrameDataView(frame, 0, HierarchyFrameDataView.ViewModes.MergeSamplesWithTheSameName,
 49	                   HierarchyFrameDataView.columnTotalTime, false))
 50	        {
 51	            sb.AppendLine($"스레드 {view.threadName}, 프레임 시간 {view.frameTimeMs:F3} ms");
 52	            var stack = new System.Collections.Generic.List<int> { view.GetRootItemID() };
 53	            var children = new System.Collections.Generic.List<int>();
 54	            while (stack.Count > 0)
 55	            {
 56	                int id = stack[stack.Count - 1]; stack.RemoveAt(stack.Count - 1);
 57	                string name = view.GetItemName(id);
 58	                if (name != null && name.StartsWith(FILTER))
 59	                    sb.AppendLine($"  {name}: total {view.GetItemColumnDataAsFloat(id, HierarchyFrameDataView.columnTotalTime):F4} ms, " +
 60	                                  $"calls {view.GetItemColumnDataAsFloat(id, HierarchyFrameDataView.columnCalls)}, " +
 61	                                  $"gc {view.GetItemColumnDataAsFloat(id, HierarchyFrameDataView.columnGcMemory)} B");
 62	                view.GetItemChildren(id, children);
 63	                stack.AddRange(children);
 64	            }
 65	        }
 66	        return sb.ToString();
 67	    }
