 69	    static void SelectCpuModule(ProfilerWindow w, StringBuilder sb)
 70	    {
 71	        // 공개 SelectModule이 없어 비공개 메서드·속성을 찾는다. 실패해도 진행하고 결과만 적는다.
 72	        const BindingFlags ALL = BindingFlags.Instance | BindingFlags.NonPublic | BindingFlags.Public;
 73	        MethodInfo select = typeof(ProfilerWindow).GetMethods(ALL)
 74	            .FirstOrDefault(m => m.Name == "SelectModule" && m.GetParameters().Length == 1 && m.GetParameters()[0].ParameterType == typeof(string));
 75	        if (select != null) { select.Invoke(w, new object[] { ProfilerWindow.cpuModuleIdentifier }); return; }
 76	        PropertyInfo prop = typeof(ProfilerWindow).GetProperty("selectedModuleIdentifier", ALL);
 77	        MethodInfo setter = prop?.GetSetMethod(true);
 78	        if (setter != null) { setter.Invoke(w, new object[] { ProfilerWindow.cpuModuleIdentifier }); return; }
 79	        sb.AppendLine("CPU 모듈 선택 방법 없음: " + string.Join(",", typeof(ProfilerWindow).GetMethods(ALL).Where(m => m.Name.Contains("Module")).Select(m => m.Name).Distinct()));
 80	    }
 81	
 82	    static void SetHierarchyView(ProfilerWindow w, StringBuilder sb)
 83	    {
 84	        // CPU 모듈의 보기 방식을 Hierarchy로. 공개 API가 없어 내부 속성을 쓴다 - 실패해도 진행하고 결과만 적는다.
 85	        try
 86	        {
 87	            MethodInfo getModule = typeof(ProfilerWindow).GetMethods(BindingFlags.Instance | BindingFlags.NonPublic | BindingFlags.Public)
 88	                .FirstOrDefault(m => m.Name == "GetProfilerModuleByType" && !m.IsGenericMethod);
 89	            Type cpuType = typeof(ProfilerWindow).Assembly.GetType("UnityEditorInternal.Profiling.CPUProfilerModule");
 90	            object module = getModule?.Invoke(w, new object[] { cpuType });
 91	            PropertyInfo viewType = cpuType?.GetProperty("ViewType", BindingFlags.Instance | BindingFlags.NonPublic | BindingFlags.Public);
 92	            if (module != null && viewType != null)
 93	            {
 94	                viewType.SetValue(module, Enum.ToObject(viewType.PropertyType, 0));
 95	                sb.AppendLine("보기: " + viewType.GetValue(module));
 96	            }
 97	            else sb.AppendLine($"보기 설정 못함 (module {module != null}, ViewType {viewType != null})");
 98	        }
 99	        catch (Exception e) { sb.AppendLine("보기 설정 예외: " + e.GetType().Name + " " + e.Message); }
100	    }
